# urdb_client.py
# Classes for interacting with the Utility Rate Database
import csv
import logging
from importlib.resources import files as _pkg_files
import polars as pl
import requests
import json
from typing import Dict, Any, Optional, List, Set
from datetime import datetime, timezone
from dataclasses import dataclass
from dateutil import parser as date_parser

logger = logging.getLogger(__name__)

# Path to the bundled utility-companies CSV (generated by scripts/fetch_utility_companies.py)
_UTILITY_CSV = _pkg_files("buildstock_rate_impact_calculator.data").joinpath(
    "utility_companies.csv"
)


@dataclass
class RateStructure:
    """Data class to hold different components of a rate structure."""

    energy_rates: pl.DataFrame
    demand_rates: pl.DataFrame
    tou_periods: pl.DataFrame
    seasonal_rates: pl.DataFrame


class URDBClient:
    """
    Client for interacting with OpenEI's Utility Rate Database (URDB).

    Provides methods to search and fetch utility rate data, including
    smart methods to find applicable current rates prioritized by NREL vetting.
    Documentation: https://openei.org/services/doc/rest/util_rates/?version=3

    Attributes:
        api_key (str): OpenEI API key for authentication
        base_url (str): Base URL for the URDB API
        default_timeout (int): Default timeout for API requests in seconds.
    """

    def __init__(self, api_key: str, default_timeout: int = 30):
        """
        Initialize the URDB client.

        Args:
            api_key (str): OpenEI API key for authentication.
            default_timeout (int): Default timeout for API requests.
        """
        if not api_key:
            raise ValueError("API key must be provided for URDBClient.")
        self.api_key = api_key
        self.base_url = "https://api.openei.org/utility_rates"
        self.default_timeout = default_timeout

    def _search_rates_api(self, params: Dict[str, Any]) -> List[Dict[Any, Any]]:
        """
        Private helper to make the API request and handle basic response.

        Args:
            params: Dictionary of parameters for the API request.

        Returns:
            List of rate items from the API response.

        Raises:
            Exception: For request errors or API-reported errors.
        """
        try:
            log_params = {
                k: ("***" if k == "api_key" else v) for k, v in params.items()
            }
            logger.info("URDB API request: %s params=%s", self.base_url, log_params)
            response = requests.get(
                self.base_url, params=params, timeout=self.default_timeout
            )
            response.raise_for_status()  # Raises HTTPError for bad responses (4XX or 5XX)

            data = response.json()
            if "error" in data:  # API specific error message
                raise ValueError(f"URDB API returned error: {data['error']}")

            logger.info(
                "URDB API request successful: %s, items returned: %d",
                response.url,
                len(data.get("items", [])),
            )
            return data.get("items", [])

        except requests.exceptions.Timeout as e:
            raise Exception(f"URDB API request timed out: {e}") from e
        except (
            requests.exceptions.RequestException
        ) as e:  # Covers HTTPError, ConnectionError, etc.
            raise Exception(f"URDB API request failed: {e}") from e
        except json.JSONDecodeError as e:
            # Log more info for JSON errors as they can be tricky
            error_msg = f"Failed to decode JSON response from URDB API: {e}. "
            error_msg += f"URL: {response.url if 'response' in locals() else 'N/A'}, "
            error_msg += (
                f"Status: {response.status_code if 'response' in locals() else 'N/A'}, "
            )
            error_msg += f"Response text (first 500 chars): {response.text[:500] if 'response' in locals() else 'N/A'}"
            raise Exception(error_msg) from e

    def search_rates_by_location_raw(
        self,
        lat: float,
        lon: float,
        radius: int = 50,
        sector: Optional[str] = None,
        limit: int = 25,  # Default to a moderate number for raw search
        orderby: str = "startdate",  # Default to sort by effective date
        direction: str = "desc",  # Default to newest first
    ) -> List[Dict[Any, Any]]:
        """
        Search for utility rates at a location (raw API results, minimally processed).
        Results are typically sorted by startdate descending by default.

        Args:
            lat: Latitude of the location.
            lon: Longitude of the location.
            radius: Search radius in miles.
            sector: Optional filter by sector ('Residential', 'Commercial', etc.).
            limit: Maximum number of records to retrieve.
            orderby: Field to sort results by (e.g., 'startdate', 'label').
            direction: Sort direction ('asc' or 'desc').

        Returns:
            List of utility rates as dictionaries from the API.
        """
        params = {
            "api_key": self.api_key,
            "lat": lat,
            "lon": lon,
            "radius": radius,
            "version": "latest",
            "format": "json",
            "detail": "full",
            "limit": limit,
            "orderby": orderby,
            "direction": direction,
        }
        if sector:
            params["sector"] = sector

        return self._search_rates_api(params)

    def get_rate_by_label(self, rate_label: str) -> Optional[Dict[Any, Any]]:
        """
        Fetch detailed utility rate data using its specific URDB label (ID).

        Args:
            rate_label: OpenEI rate label (ID).

        Returns:
            Rate data dictionary if found, None otherwise.
        """
        params = {
            "api_key": self.api_key,
            "version": "latest",
            "format": "json",
            "detail": "full",
            "getpage": rate_label,  # 'getpage' is used for specific label lookup
        }

        items = self._search_rates_api(params)
        return items[0] if items else None

    def get_utility_companies(self) -> List[Dict[str, str]]:
        """
        Load utility company names and aliases from the bundled CSV.

        The CSV is generated once by running ``pixi run fetch-utilities`` which
        calls the OpenEI MediaWiki categorymembers API and writes all ~3 800
        entries to ``src/buildstock_rate_impact_calculator/data/utility_companies.csv``.

        Each returned dict has:
          * ``label``          — wiki page title (accepted by ``ratesforutility``)
          * ``uri``            — full OpenEI wiki URI
          * ``eia_utility_id`` — EIA utility ID string (may be empty)

        Returns:
            List of dicts with keys ``label``, ``uri``, and ``eia_utility_id``.

        Raises:
            FileNotFoundError: If the CSV has not been generated yet.
        """
        logger.debug("Loading utility companies from bundled CSV: %s", _UTILITY_CSV)
        items: List[Dict[str, str]] = []
        with _UTILITY_CSV.open("r", encoding="utf-8", newline="") as fh:
            reader = csv.DictReader(fh)
            for row in reader:
                items.append(
                    {
                        "label": row["label"],
                        "uri": row["uri"],
                        "eia_utility_id": row.get("eia_utility_id", ""),
                    }
                )
        logger.debug("Loaded %d utility companies from CSV", len(items))
        return items

    def search_rates_by_utility_raw(
        self,
        utility_name: str,
        sector: Optional[str] = None,
        servicetype: Optional[str] = None,
        effective_as_of: Optional[int] = None,
        limit: int = 25,
        orderby: str = "startdate",
        direction: str = "desc",
    ) -> List[Dict[Any, Any]]:
        """
        Search for rates by utility name (raw API results, minimally processed).
        Results are typically sorted by startdate descending by default.

        Args:
            utility_name: Name of the utility company.
            sector: Optional filter by sector ('Residential', 'Commercial', etc.).
            servicetype: Optional service type filter ('Bundled', 'Energy', 'Delivery',
                'Delivery with Standard Offer').
            effective_as_of: Optional Unix timestamp; only rates where startdate <= this
                timestamp <= enddate (or enddate is absent/empty) are returned.
            limit: Maximum number of records to retrieve.
            orderby: Field to sort results by.
            direction: Sort direction.

        Returns:
            List of matching utility rates as dictionaries from the API.
        """
        # The documented 'ratesforutility' parameter requires an exact utility page-slug
        # match and does not support partial/fuzzy name search. The undocumented 'utility'
        # parameter performs a partial name search and is what the UI search box requires.
        params = {
            "api_key": self.api_key,
            "version": "latest",
            "format": "json",
            "detail": "full",
            "ratesforutility": utility_name,
            "limit": limit,
            "orderby": orderby,
            "direction": direction,
        }
        if sector:
            params["sector"] = sector
        if servicetype:
            params["servicetype"] = servicetype
        results = self._search_rates_api(params)
        if effective_as_of is not None:
            filtered = []
            for r in results:
                start = r.get("startdate")
                end = r.get("enddate")
                start_ts = int(start) if start else None
                end_ts = int(end) if end else None
                if start_ts is not None and effective_as_of < start_ts:
                    continue
                if end_ts is not None and effective_as_of > end_ts:
                    continue
                filtered.append(r)
            results = filtered
        return results

    def get_applicable_rates_for_location(
        self,
        lat: float,
        lon: float,
        sector: Optional[str] = None,
        radius: int = 50,
        limit_raw_search: int = 50,
    ) -> List[Dict[Any, Any]]:
        """
        Finds applicable and current rates for a location, prioritizing NREL vetted.

        The process is:
        1. Fetch candidate rates (sorted by newest startdate from API).
        2. Filter for currently active rates.
        3. Sort the current rates: NREL "approved" first, then by newest startdate.

        Args:
            lat: Latitude of the location.
            lon: Longitude of the location.
            sector: Optional sector to filter by.
            radius: Search radius in miles.
            limit_raw_search: How many raw candidates to fetch from API initially.

        Returns:
            A list of rate dictionaries, sorted by priority (NREL vetted first, then newest).
            Empty list if no suitable rates are found.
        """
        candidate_rates = self.search_rates_by_location_raw(
            lat=lat,
            lon=lon,
            radius=radius,
            sector=sector,
            limit=limit_raw_search,
            orderby="startdate",
            direction="desc",
        )

        if not candidate_rates:
            return []

        # Filter for current rates
        current_rates = [
            rate for rate in candidate_rates if RateAnalyzer.is_rate_current(rate)
        ]

        if not current_rates:
            return []

        # Sort: primary key 'approved' (True first), secondary key 'startdate' (desc)
        # 'approved' is boolean. For sorting, True > False.
        # 'startdate' is integer timestamp. Larger (newer) timestamp is better.
        def sort_key(rate_item):
            is_approved = (
                rate_item.get("approved", False) == True
            )  # Explicitly check for True
            # API stores startdate as integer timestamp
            start_timestamp = rate_item.get("startdate", 0)
            if not isinstance(start_timestamp, (int, float)):  # Should be int from API
                start_timestamp = 0  # Fallback for bad data

            # Sort: approved (True) first, then by newest startdate (largest timestamp)
            # Python's sort is stable, so initial sort by startdate from API helps
            # Forcing approved=True to be "smaller" in sort order makes it come first with reverse=True on approved
            return (not is_approved, -float(start_timestamp))

        prioritized_rates = sorted(current_rates, key=sort_key)

        return prioritized_rates

    def get_applicable_rates_for_utility(
        self,
        utility_name: str,
        sector: Optional[str] = None,
        limit_raw_search: int = 50,
    ) -> List[Dict[Any, Any]]:
        """
        Finds applicable and current rates for a utility, prioritizing NREL vetted.

        Process is similar to get_applicable_rates_for_location.
        Args:
            utility_name: Name of the utility.
            sector: Optional sector to filter by.
            limit_raw_search: How many raw candidates to fetch initially.

        Returns:
            A list of rate dictionaries, sorted by priority.
        """
        candidate_rates = self.search_rates_by_utility_raw(
            utility_name=utility_name,
            sector=sector,
            limit=limit_raw_search,
            orderby="startdate",
            direction="desc",
        )

        if not candidate_rates:
            return []

        current_rates = [
            rate for rate in candidate_rates if RateAnalyzer.is_rate_current(rate)
        ]

        if not current_rates:
            return []

        def sort_key(rate_item):
            is_approved = rate_item.get("approved", False) == True
            start_timestamp = rate_item.get("startdate", 0)
            if not isinstance(start_timestamp, (int, float)):
                start_timestamp = 0
            return (not is_approved, -float(start_timestamp))

        prioritized_rates = sorted(current_rates, key=sort_key)

        return prioritized_rates


class RateAnalyzer:
    """
    Analyze and parse utility rate data from URDB.

    This class provides methods to parse and analyze rate structures including
    energy rates, demand charges, Time-of-Use (TOU) periods, and seasonal variations,
    as well as utility methods for rate metadata like date checking.
    """

    @staticmethod
    def _parse_urdb_date(date_val: Any) -> Optional[datetime]:
        """
        Parses a date value from URDB (str or timestamp) into a tz-aware UTC datetime.
        Handles potential timestamp range errors. URDB API states 'startdate' and
        'enddate' are integer timestamps.

        Args:
            date_val: The date value from the URDB data (string, int, float, None).

        Returns:
            A timezone-aware datetime object in UTC, or None if parsing fails or input is None.
        """
        if date_val is None:
            return None

        try:
            # TODO: This section still uses some workarounds and is not checked in detail and
            # cleaned up. Needs proper checking and review.

            if isinstance(date_val, (int, float)):
                # URDB 'startdate'/'enddate' are integer timestamps (seconds since epoch)
                date_val_seconds = float(date_val)
                # Check for common case of milliseconds if value is excessively large for seconds
                # A common threshold: year 2200 timestamp is approx 7,258,000,000
                # If date_val is e.g. 1.5e12, it's likely ms.
                if (
                    date_val_seconds > 8_000_000_000
                    and date_val_seconds > datetime.now().timestamp() * 100
                ):  # Heuristic for ms
                    date_val_seconds /= 1000.0

                # Ensure the timestamp is within a reasonable range for datetime.utcfromtimestamp
                # Min/max supported by fromtimestamp can be platform-dependent.
                # A practical range for URDB dates (e.g., 1970 to ~2300)
                if not (0 <= date_val_seconds <= 10_000_000_000):  # Approx year 2286
                    # print(f"Warning: Timestamp {date_val} is outside typical range, may cause parsing issues.")
                    # Attempting to parse anyway, but this might fail on some systems if too extreme
                    pass

                naive_dt = datetime.utcfromtimestamp(date_val_seconds)
                return naive_dt.replace(tzinfo=timezone.utc)

            elif isinstance(date_val, str) and date_val.strip():
                # Fallback for string dates if API ever changes or for other date fields
                parsed_date = date_parser.parse(date_val)
                if (
                    parsed_date.tzinfo is None
                    or parsed_date.tzinfo.utcoffset(parsed_date) is None
                ):
                    return parsed_date.replace(tzinfo=timezone.utc)
                else:
                    return parsed_date.astimezone(timezone.utc)
            else:
                return None
        except (
            ValueError,
            OverflowError,
            TypeError,
            OSError,
            date_parser.ParserError,
        ):
            # print(f"Debug: Failed to parse/convert date '{date_val}': {e}") # Optional debug
            return None

    @staticmethod
    def is_rate_current(
        rate_data: Dict[str, Any], reference_time_utc: Optional[datetime] = None
    ) -> bool:
        """
        Checks if a URDB rate is likely current based on its start/end dates.

        Args:
            rate_data: The rate data dictionary from URDB.
            reference_time_utc: Optional datetime object to compare against (defaults to now UTC).

        Returns:
            True if the rate is considered current, False otherwise.
        """
        if reference_time_utc is None:
            reference_time_utc = datetime.now(timezone.utc)
        elif reference_time_utc.tzinfo is None:
            reference_time_utc = reference_time_utc.replace(tzinfo=timezone.utc)

        start_datetime = RateAnalyzer._parse_urdb_date(rate_data.get("startdate"))
        end_datetime = RateAnalyzer._parse_urdb_date(rate_data.get("enddate"))

        if start_datetime and reference_time_utc < start_datetime:
            return False

        if end_datetime and reference_time_utc >= end_datetime:
            return False

        return True

    @staticmethod
    def parse_rate_schedule(rate_data: Dict[Any, Any]) -> RateStructure:
        """
        Parse the complete rate schedule including TOU and seasonal variations.

        Args:
            rate_data: Rate data dictionary from URDB

        Returns:
            RateStructure object containing DataFrames for various rate components
        """
        # Validate input
        if not rate_data or not isinstance(rate_data, dict):
            return RateStructure(
                energy_rates=pl.DataFrame(),
                demand_rates=pl.DataFrame(),
                tou_periods=pl.DataFrame(),
                seasonal_rates=pl.DataFrame(),
            )

        # Parse energy rate structure
        energy_periods = []
        if "energyratestructure" in rate_data and isinstance(
            rate_data["energyratestructure"], list
        ):
            for period_idx, period_rates in enumerate(rate_data["energyratestructure"]):
                if not isinstance(period_rates, list):
                    continue
                for tier_idx, rate_tier in enumerate(period_rates):
                    if not isinstance(rate_tier, dict):
                        continue
                    period_data = {
                        "period": period_idx,  # PySAM uses 0-indexed for schedules mapping to 1-indexed matrix
                        "tier": tier_idx,  # PySAM uses 0-indexed for schedules mapping to 1-indexed matrix
                        "rate": rate_tier.get("rate", 0.0),
                        "adj": rate_tier.get("adj", 0.0),
                        "sell": rate_tier.get("sell", 0.0),  # Important for PySAM
                        "max_usage_kwh": rate_tier.get("max")
                        if rate_tier.get("unit", "").lower() == "kwh"
                        else rate_tier.get("max", float("inf")),
                        "unit_pysam": rate_tier.get(
                            "unit"
                        ),  # 'kWh', 'kWh/kW', 'kWh daily', 'kWh/kW daily'
                        # Store original unit for clarity, PySAM mapping needs care
                    }
                    energy_periods.append(period_data)

        # Parse demand rate structure
        demand_periods = []
        if "demandratestructure" in rate_data and isinstance(
            rate_data["demandratestructure"], list
        ):
            for period_idx, period_rates in enumerate(rate_data["demandratestructure"]):
                if not isinstance(period_rates, list):
                    continue
                for tier_idx, rate_tier in enumerate(period_rates):
                    if not isinstance(rate_tier, dict):
                        continue
                    period_data = {
                        "period": period_idx,
                        "tier": tier_idx,
                        "rate": rate_tier.get("rate", 0.0),
                        "adj": rate_tier.get("adj", 0.0),
                        "max_demand_kw": rate_tier.get("max", float("inf")),
                    }
                    demand_periods.append(period_data)

        # Parse seasonal definitions
        seasons = []
        if "seasonaldefinitions" in rate_data and isinstance(
            rate_data["seasonaldefinitions"], list
        ):
            for season_def in rate_data["seasonaldefinitions"]:
                if not isinstance(season_def, dict):
                    continue
                seasons.append(
                    {
                        "season_name": season_def.get("name", f"Season{len(seasons)}"),
                        "start_month": season_def.get("startmonth"),
                        "start_day": season_def.get("startday"),
                        "end_month": season_def.get("endmonth"),
                        "end_day": season_def.get("endday"),
                    }
                )

        # Parse TOU periods
        tou_periods_df = RateAnalyzer._extract_tou_periods(rate_data)

        return RateStructure(
            energy_rates=pl.DataFrame(energy_periods)
            if energy_periods
            else pl.DataFrame(
                schema={
                    "period": pl.Int64,
                    "tier": pl.Int64,
                    "rate": pl.Float64,
                    "adj": pl.Float64,
                    "sell": pl.Float64,
                    "max_usage_kwh": pl.Float64,
                    "unit_pysam": pl.Utf8,
                }
            ),
            demand_rates=pl.DataFrame(demand_periods)
            if demand_periods
            else pl.DataFrame(
                schema={
                    "period": pl.Int64,
                    "tier": pl.Int64,
                    "rate": pl.Float64,
                    "adj": pl.Float64,
                    "max_demand_kw": pl.Float64,
                }
            ),
            tou_periods=tou_periods_df,  # Already a DataFrame
            seasonal_rates=pl.DataFrame(seasons)
            if seasons
            else pl.DataFrame(
                schema={
                    "season_name": pl.Utf8,
                    "start_month": pl.Int64,
                    "start_day": pl.Int64,
                    "end_month": pl.Int64,
                    "end_day": pl.Int64,
                }
            ),
        )

    @staticmethod
    def get_rate_summary(rate_data: Dict[str, Any]) -> Dict[str, Any]:
        """
        Create a summary of the rate structure. Includes parsed date objects.

        Args:
            rate_data: Rate data dictionary from URDB

        Returns:
            Dictionary containing summary of the rate structure
        """
        summary = {
            "utility_name": rate_data.get("utility", "N/A"),
            "rate_name": rate_data.get("name", "N/A"),
            "rate_label": rate_data.get(
                "label", "N/A"
            ),  # Changed from rate_id to match API field
            "fixed_monthly_charge": float(rate_data.get("fixedmonthlycharge", 0.0)),
            "min_monthly_charge": float(rate_data.get("minmonthlycharge", 0.0)),
            "annual_min_charge": float(rate_data.get("annualmincharge", 0.0)),
            "source": rate_data.get("source", "N/A"),
            "sector": rate_data.get("sector", "N/A"),
            "description": rate_data.get("description", "N/A")[:200] + "..."
            if rate_data.get("description")
            and len(rate_data.get("description", "")) > 200
            else rate_data.get("description", "N/A"),
            "approved_by_expert": rate_data.get("approved", False),
            "has_tou_energy_rates": bool(
                rate_data.get("energyweekdayschedule")
            ),  # Simpler check
            "has_demand_charges": bool(rate_data.get("demandratestructure")),
            "has_tou_demand_rates": bool(
                rate_data.get("demandweekdayschedule")
                and rate_data.get("demandratestructure")
            ),
            # 'has_seasonal_rates': bool(rate_data.get('seasonaldefinitions')), # Not directly used by PySAM UtilityRate5 in this way
            "startdate_str": str(rate_data.get("startdate", "N/A")),
            "enddate_str": str(rate_data.get("enddate", "N/A")),
            "startdate_obj_utc": RateAnalyzer._parse_urdb_date(
                rate_data.get("startdate")
            ),
            "enddate_obj_utc": RateAnalyzer._parse_urdb_date(rate_data.get("enddate")),
            "is_current": RateAnalyzer.is_rate_current(rate_data),
            "uri": rate_data.get("uri", "N/A"),
            "summary_generated_utc": datetime.now(timezone.utc).isoformat(),
        }
        # Convert datetimes to ISO strings for JSON serializability if summary is dumped
        if summary["startdate_obj_utc"]:
            summary["startdate_obj_utc"] = summary["startdate_obj_utc"].isoformat()
        if summary["enddate_obj_utc"]:
            summary["enddate_obj_utc"] = summary["enddate_obj_utc"].isoformat()
        return summary

    @staticmethod
    def _extract_tou_periods(rate_data: Dict[Any, Any]) -> pl.DataFrame:
        """
        Extract Time-of-Use (TOU) periods from rate data for human-readable summary.
        This identifies distinct period definitions from schedules.

        Args:
            rate_data: Rate data dictionary from URDB

        Returns:
            DataFrame containing TOU period definitions summary
        """
        all_period_defs = []

        def process_schedule_for_summary(
            schedule_type: str,  # 'Energy' or 'Demand'
            weekday_sched_key: str,
            weekend_sched_key: str,
            rate_struct_key: str,
        ):
            weekday_schedule = rate_data.get(weekday_sched_key)
            weekend_schedule = rate_data.get(weekend_sched_key)

            if not isinstance(weekday_schedule, list) or not isinstance(
                weekend_schedule, list
            ):
                return  # Schedules not present or malformed

            # Ensure schedules are 12x24
            if not (
                len(weekday_schedule) == 12
                and all(len(m) == 24 for m in weekday_schedule if isinstance(m, list))
                and len(weekend_schedule) == 12
                and all(len(m) == 24 for m in weekend_schedule if isinstance(m, list))
            ):
                # print(f"Warning: Schedule {weekday_sched_key} or {weekend_sched_key} is not 12x24, skipping TOU summary for it.")
                return

            # period_id -> {months: set(), weekday_hours: set(), weekend_hours: set()}
            active_periods_info: Dict[int, Dict[str, Set[Any]]] = {}

            for month_idx in range(12):
                for hour_idx in range(24):
                    # Weekday
                    wd_period_idx = weekday_schedule[month_idx][hour_idx]
                    if not isinstance(wd_period_idx, int):
                        continue  # Skip non-integer period indices
                    if wd_period_idx not in active_periods_info:
                        active_periods_info[wd_period_idx] = {
                            "months": set(),
                            "weekday_hours": set(),
                            "weekend_hours": set(),
                        }
                    active_periods_info[wd_period_idx]["months"].add(month_idx + 1)
                    active_periods_info[wd_period_idx]["weekday_hours"].add(hour_idx)

                    # Weekend
                    we_period_idx = weekend_schedule[month_idx][hour_idx]
                    if not isinstance(we_period_idx, int):
                        continue
                    if we_period_idx not in active_periods_info:
                        active_periods_info[we_period_idx] = {
                            "months": set(),
                            "weekday_hours": set(),
                            "weekend_hours": set(),
                        }
                    active_periods_info[we_period_idx]["months"].add(month_idx + 1)
                    active_periods_info[we_period_idx]["weekend_hours"].add(hour_idx)

            rate_structure = rate_data.get(rate_struct_key, [])
            if not isinstance(rate_structure, list):
                rate_structure = []

            for period_idx_from_schedule, info in active_periods_info.items():
                # URDB schedules are 0-indexed for periods.
                # PySAM expects 1-indexed period numbers in the rate matrices.
                # The period_idx_from_schedule is what's IN the schedule array.

                # Find the rate for this period_idx_from_schedule (0-indexed)
                rate_val = "N/A"
                unit = "$/kWh" if schedule_type == "Energy" else "$/kW"
                tier_info = "Single Tier"

                if 0 <= period_idx_from_schedule < len(rate_structure):
                    period_tiers = rate_structure[period_idx_from_schedule]
                    if isinstance(period_tiers, list) and period_tiers:
                        first_tier = period_tiers[0]
                        if isinstance(first_tier, dict) and "rate" in first_tier:
                            rate_val = first_tier["rate"]
                        if len(period_tiers) > 1:
                            tier_info = f"{len(period_tiers)} Tiers"

                all_period_defs.append(
                    {
                        "type": schedule_type,
                        "period_index_in_schedule": period_idx_from_schedule,  # 0-indexed as in schedule
                        "pysam_period_label": period_idx_from_schedule
                        + 1,  # 1-indexed for PySAM matrix
                        "months_active": RateAnalyzer._format_month_ranges(
                            sorted(list(info["months"]))
                        ),
                        "weekday_hours": RateAnalyzer._format_hour_ranges(
                            sorted(list(info["weekday_hours"]))
                        ),
                        "weekend_hours": RateAnalyzer._format_hour_ranges(
                            sorted(list(info["weekend_hours"]))
                        ),
                        "representative_rate": rate_val,
                        "tier_info": tier_info,
                        "unit": unit,
                    }
                )

        process_schedule_for_summary(
            "Energy",
            "energyweekdayschedule",
            "energyweekendschedule",
            "energyratestructure",
        )
        process_schedule_for_summary(
            "Demand",
            "demandweekdayschedule",
            "demandweekendschedule",
            "demandratestructure",
        )

        if not all_period_defs:
            return pl.DataFrame(
                schema={  # Ensure schema consistency for empty DFs
                    "type": pl.Utf8,
                    "period_index_in_schedule": pl.Int64,
                    "pysam_period_label": pl.Int64,
                    "months_active": pl.Utf8,
                    "weekday_hours": pl.Utf8,
                    "weekend_hours": pl.Utf8,
                    "representative_rate": pl.Float64,
                    "tier_info": pl.Utf8,
                    "unit": pl.Utf8,
                }
            )

        return pl.DataFrame(all_period_defs)

    @staticmethod
    def _format_hour_ranges(hours: List[int]) -> str:
        if not hours:
            return "None"
        hours = sorted(list(set(hours)))  # Ensure unique and sorted
        if not hours:
            return "None"

        ranges = []
        start_hour_in_sequence = hours[0]
        for i in range(1, len(hours)):
            if hours[i] != hours[i - 1] + 1:  # Break in sequence
                ranges.append(
                    f"{RateAnalyzer._format_hour(start_hour_in_sequence)}-{RateAnalyzer._format_hour(hours[i - 1] + 1)}"
                )
                start_hour_in_sequence = hours[i]
        ranges.append(
            f"{RateAnalyzer._format_hour(start_hour_in_sequence)}-{RateAnalyzer._format_hour(hours[-1] + 1)}"
        )
        return ", ".join(ranges)

    @staticmethod
    def _format_hour(hour: int) -> str:
        # Hour is 0-23 for start of hour, end of hour can be 24 (midnight next day)
        if hour == 0:
            return "12am"
        if hour == 24:
            return "12am (next day)"  # For end of range
        if hour == 12:
            return "12pm"
        if hour < 12:
            return f"{hour}am"
        return f"{hour - 12}pm"

    @staticmethod
    def _format_month_ranges(months: List[int]) -> str:
        if not months:
            return "None"
        months = sorted(list(set(months)))  # Ensure unique and sorted (1-12)
        if not months:
            return "None"
        if len(months) == 12 and months == list(range(1, 13)):
            return "All Year"

        month_names = [
            "Jan",
            "Feb",
            "Mar",
            "Apr",
            "May",
            "Jun",
            "Jul",
            "Aug",
            "Sep",
            "Oct",
            "Nov",
            "Dec",
        ]

        ranges = []
        start_month_in_sequence = months[0]
        for i in range(1, len(months)):
            if months[i] != months[i - 1] + 1:  # Break in sequence
                current_range_end_month = month_names[months[i - 1] - 1]
                if start_month_in_sequence == months[i - 1]:  # Single month
                    ranges.append(current_range_end_month)
                else:
                    ranges.append(
                        f"{month_names[start_month_in_sequence - 1]}-{current_range_end_month}"
                    )
                start_month_in_sequence = months[i]

        # Last sequence or single month
        final_range_end_month = month_names[months[-1] - 1]
        if start_month_in_sequence == months[-1]:
            ranges.append(final_range_end_month)
        else:
            ranges.append(
                f"{month_names[start_month_in_sequence - 1]}-{final_range_end_month}"
            )
        return ", ".join(ranges)
